import { HomeMain } from '../../slots/defs/homeMain';
import { VoidReasons } from './VoidReasons';

export const contribution = HomeMain.fill({ order: 9.75, Component: VoidReasons });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey, useCurrentSheet } from '../session/session';

/** The query key for the sheet's void reasons; under sheetKey, so re-loading the sheet re-reads them. */
export const voidReasonsKey = (sheet: string) => [...sheetKey(sheet), 'void-reasons'] as const;

/**
 * The sheet's void reasons, in the order they were added. While the list is not empty, a claim is voided only with a
 * reason chosen from it.
 */
export function useVoidReasons() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: voidReasonsKey(sheet),
    queryFn: () => getJson<string[]>(`/api/sheets/${encodeURIComponent(sheet)}/void-reasons`),
    enabled: !!sheet,
  });
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { useVoidReasons, voidReasonsKey } from './voidReasons';
import { useOneAtATime } from '../../query/useOneAtATime';

// The sheet's void reasons and the entry a reason is added to them with; a blank reason or one already on the list is
// refused.
export function VoidReasons() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const reasons = useVoidReasons().data ?? [];
  const [text, setText] = useState('');
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const add = useMutation({
    mutationFn: (input: { reason: string }) =>
      postJson<string[]>(`/api/sheets/${encodeURIComponent(sheet)}/void-reasons?user=${encodeURIComponent(user)}`, input),
    onSuccess: async (saved) => {
      setText('');
      setError('');
      queryClient.setQueryData(voidReasonsKey(sheet), saved);
      await queryClient.invalidateQueries({ queryKey: voidReasonsKey(sheet) });
    },
    onError: () => setError('That void reason was refused: it is blank or already on the list.'),
  });

  if (!user || !sheet) return null;

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const reason = text.trim();
    if (!reason) {
      setError('Type the void reason.');
      return;
    }
    if (reasons.includes(reason)) {
      setError(`${reason} is already a void reason.`);
      return;
    }
    once(() => add.mutateAsync({ reason }));
  };

  return (
    <section data-testid="void-reasons">
      <ul data-testid="void-reason-list">
        {reasons.map((r) => (
          <li key={r} data-testid={`void-reason-row-${r}`}>
            {r}
          </li>
        ))}
      </ul>
      <form onSubmit={submit} data-testid="void-reason-form">
        <input
          data-testid="void-reason-text"
          placeholder="Void reason"
          value={text}
          onChange={(e) => {
            setText(e.target.value);
            setError('');
          }}
        />
        <button type="submit" data-testid="void-reason-add" disabled={add.isPending}>
          Add void reason
        </button>
        {error && <span data-testid="void-reason-error">{error}</span>}
      </form>
    </section>
  );
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey, useCurrentSheet } from '../session/session';

/** The query key for the sheet's holidays; under sheetKey, so re-loading the sheet re-reads them. */
export const holidaysKey = (sheet: string) => [...sheetKey(sheet), 'holidays'] as const;

/**
 * The sheet's holidays (yyyy-MM-dd), earliest first. A claim's due-by, fixed when it is created, that falls on one
 * moves to the next day that is not one; a holiday added later leaves existing due-by dates as they are.
 */
export function useHolidays() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: holidaysKey(sheet),
    queryFn: () => getJson<string[]>(`/api/sheets/${encodeURIComponent(sheet)}/holidays`),
    enabled: !!sheet,
  });
}
import { HomeMain } from '../../slots/defs/homeMain';
import { Holidays } from './Holidays';

export const contribution = HomeMain.fill({ order: 9.7, Component: Holidays });
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}

