-- A holiday on a sheet: a claim's due-by, fixed when it is created, that would fall on one moves to the next day
-- that is not one. A date is on a sheet's list at most once.
CREATE TABLE holiday (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    holiday_date DATE NOT NULL,
    PRIMARY KEY (sheet_id, holiday_date)
);
-- A claim's comments, oldest first (id order): the text, the user who wrote it and the sheet's today then.
CREATE TABLE claim_comment (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    claim_id BIGINT NOT NULL REFERENCES claim (id),
    by_user VARCHAR(200) NOT NULL,
    comment_date DATE NOT NULL,
    text VARCHAR(4000) NOT NULL
);
CREATE INDEX claim_comment_sheet ON claim_comment (sheet_id, claim_id, id);
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadSheet {
    public void load(@PathVariable("sheetId") String sheetId, SheetRepository repository, Out<Sheet> sheet)
            throws SheetNotFoundException {
        Sheet found = repository.find(sheetId);
        if (found == null) {
            throw new SheetNotFoundException(sheetId);
        }
        sheet.set(found);
    }
}

